    <div class="field"><label>กลุ่มขนาดเครื่องยนต์</label><select name="engineGroup" id="car-engine-group-select"><option value="">เลือกกลุ่มเครื่องยนต์</option>${['ไม่เกิน 1,200 ซีซี','1,201–1,500 ซีซี','1,501–1,800 ซีซี','1,801–2,000 ซีซี','2,001–2,500 ซีซี','มากกว่า 2,500 ซีซี'].map(x=>`<option value="${x}" ${(old?.engineGroup||(old?.engineCc?engineCcGroup(Number(old.engineCc)):'') )===x?'selected':''}>${x}</option>`).join('')}</select><small id="car-engine-group-hint" class="photo-help">เลือกช่วงซีซีของรถ</small></div>
