function engineCcGroup(cc){
  if(cc<=1200)return 'ไม่เกิน 1,200 ซีซี';
  if(cc<=1500)return '1,201–1,500 ซีซี';
  if(cc<=1800)return '1,501–1,800 ซีซี';
  if(cc<=2000)return '1,801–2,000 ซีซี';
  if(cc<=2500)return '2,001–2,500 ซีซี';
  return 'มากกว่า 2,500 ซีซี';
}
