function renderQuotes(){if(!$('#quotes-table'))return;const rows=(db.quotes||[]).slice().sort((a,b)=>b.created.localeCompare(a.created));$('#quotes-table').innerHTML=rows.map(q=>`<tr><td>${q.id}<span class="subtext">${dateFmt(q.created)}</span></td><td>${esc(customer(q.customerId)?.name||'')}</td><td>${esc(car(q.carId)?.name||'')}<span class="subtext">${esc(car(q.carId)?.plate||'')}</span></td><td>${dtFmt(q.start)} – ${dtFmt(q.end)}<span class="subtext">${q.days} วัน</span></td><td><b>${money(q.total)}</b></td><td><span class="status status-${q.status==='converted'?'confirmed':q.status==='cancelled'?'cancelled':'quoted'}">${({quoted:'เสนอราคาแล้ว',converted:'เปลี่ยนเป็นรายการเช่าแล้ว',expired:'หมดอายุ',cancelled:'ยกเลิก'})[q.status]||q.status}</span></td><td><button class="text-button" data-quote-print="${q.id}">พิมพ์ใบเสนอราคา</button>${q.status==='quoted'?`<button class="text-button" data-quote-convert="${q.id}">สร้างรายการเช่า</button>`:''}</td></tr>`).join('');$('#quotes-empty').classList.toggle('hidden',rows.length>0);$$('[data-quote-convert]').forEach(b=>b.onclick=()=>bookingForm('',b.dataset.quoteConvert));$$('[data-quote-print]').forEach(b=>b.onclick=()=>printQuote(b.dataset.quotePrint))}
function printQuote(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;const c=customer(q.customerId),v=car(q.carId);openModal('ใบเสนอราคา',`เลขที่ ${q.id}`,`<div class="receipt"><div class="receipt-brand"><b>AB CARRENT</b><span>รถเช่านครศรีธรรมราช</span><small>โทร. 081-234-5678</small></div><h3>ใบเสนอราคา</h3><div class="receipt-info"><div><span>ลูกค้า</span><br>${esc(c?.taxName||c?.name||'')}</div><div><span>วันที่ออก</span><br>${dateFmt(q.created)}</div><div><span>รถ</span><br>${esc(v?.name||'')} · ${esc(v?.plate||'')}</div><div><span>ช่วงเวลาเช่า</span><br>${dtFmt(q.start)} – ${dtFmt(q.end)}</div><div><span>จำนวนวัน</span><br>${q.days} วัน</div><div><span>วงเงินประกัน</span><br>${money(q.insuranceCoverage)}</div></div><div class="receipt-line"><span>ค่าเช่ารถ${q.insurance?' · '+esc(q.insurance):''}</span><span>${money(q.total-(q.extraCharges||[]).reduce((s,x)=>s+Number(x.amount),0))}</span></div>${(q.extraCharges||[]).map(x=>`<div class="receipt-line"><span>${esc(x.title)}</span><span>${money(x.amount)}</span></div>`).join('')}<div class="receipt-line"><span>เงินมัดจำ</span><span>${money(q.deposit)}</span></div><div class="receipt-total"><span>ยอดเสนอ</span><span>${money(q.total)}</span></div><div class="receipt-note">ใบเสนอราคานี้ไม่ถือเป็นการยืนยันการจอง จนกว่าจะบันทึกรายการเช่า</div></div><div class="form-actions"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-quote">พิมพ์ใบเสนอราคา</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-quote').onclick=()=>window.print()}
function quoteForm(){if(!db.cars.length||!db.customers.length)return toast('เพิ่มรถและลูกค้าก่อนออกใบเสนอราคา');openModal('ออกใบเสนอราคา','กำหนดลูกค้า รถ และช่วงเวลาเช่า',`<form id="quote-form"><div class="form-grid"><div class="field full"><label>ลูกค้า *</label><select name="customerId" required>${customerOpts()}</select></div><div class="field full"><label>รถที่ว่าง *</label><select name="carId" id="quote-car" required>${carOpts()}</select></div><div class="field"><label>รับรถ *</label><input name="start" type="datetime-local" value="${todayISO()}T09:00" required></div><div class="field"><label>คืนรถ *</label><input name="end" type="datetime-local" value="${isoOffset(1)}T09:00" required></div><div class="field"><label>มัดจำ (บาท)</label><input name="deposit" type="number" min="0" value="0"></div><div class="field"><label>ประกัน / รายละเอียด</label><input name="insurance"></div><div class="field"><label>วงเงินประกัน (บาท)</label><input name="insuranceCoverage" type="number" min="0" value="0"></div><div class="field"><label>ค่าใช้จ่ายเพิ่มเติม</label><input name="extraTitle" placeholder="ค่ารถไปส่ง"></div><div class="field"><label>จำนวนเงินเพิ่ม (บาท)</label><input name="extraAmount" type="number" min="0" value="0"></div><div class="field full"><div class="price-preview"><span id="quote-calc">คำนวณราคา</span><b id="quote-total">฿0</b></div></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกใบเสนอราคา</button></div></form>`);$('.cancel-modal').onclick=closeModal;const f=$('#quote-form'),updateCars=()=>{const chosen=f.carId.value,available=db.cars.filter(c=>c.available&&!hasConflict(c.id,f.start.value,f.end.value));f.carId.innerHTML=available.map(c=>`<option value="${c.id}" ${c.id===chosen?'selected':''}>${esc(c.name)} · ${esc(c.plate)}</option>`).join('')||'<option value="">ไม่มีรถว่าง</option>';const d=duration(f.start.value,f.end.value),extra=Number(f.extraAmount.value)||0;$('#quote-calc').textContent=d?`ค่าเช่า ${d} วัน + ค่าใช้จ่ายเพิ่มเติม ${money(extra)}`:'กรุณาตรวจสอบช่วงเวลา';$('#quote-total').textContent=money(d*(car(f.carId.value)?.price||0)+extra)};f.start.onchange=f.end.onchange=updateCars;f.carId.onchange=f.extraAmount.oninput=updateCars;updateCars();f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),days=duration(d.start,d.end);if(!days||!d.carId||hasConflict(d.carId,d.start,d.end))return toast('ช่วงเวลาไม่ถูกต้องหรือรถไม่ว่าง');const extraCharges=d.extraTitle&&Number(d.extraAmount)>0?[{title:d.extraTitle,amount:Number(d.extraAmount)}]:[];db.quotes.push({id:window.__nextQuoteId||'QT-'+Date.now().toString().slice(-7),customerId:d.customerId,carId:d.carId,start:d.start,end:d.end,days,total:days*car(d.carId).price+extraCharges.reduce((s,x)=>s+x.amount,0),deposit:Number(d.deposit)||0,insurance:d.insurance||'',insuranceCoverage:Number(d.insuranceCoverage)||0,extraCharges,status:'quoted',created:todayISO()});persist();closeModal();show('quotes');toast('ออกใบเสนอราคาแล้ว')}}

let thaiGeoPromise=null;
async function thaiGeo(){if(!thaiGeoPromise)thaiGeoPromise=Promise.all(['province','district','sub_district'].map(async n=>{const r=await fetch(`https://raw.githubusercontent.com/kongvut/thai-province-data/refs/heads/master/api/latest/${n}.json`);if(!r.ok)throw new Error('โหลดข้อมูลที่อยู่ไม่สำเร็จ');return r.json()})).then(([provinces,districts,subdistricts])=>({provinces,districts,subdistricts}));return thaiGeoPromise}
function setupThaiAddress(old){const p=$('#customer-province'),d=$('#customer-district'),s=$('#customer-subdistrict'),zip=$('#customer-postal'),th=x=>x?.name?.th||'',label=x=>`${x?.prefix?.th||''}${th(x)}`;thaiGeo().then(g=>{p.innerHTML='<option value="">เลือกจังหวัด</option>'+g.provinces.map(x=>`<option>${esc(th(x))}</option>`).join('');if(old?.province){p.value=old.province;p.dispatchEvent(new Event('change'))}}).catch(()=>toast('โหลดรายชื่อจังหวัดไม่สำเร็จ ตรวจสอบอินเทอร์เน็ตแล้วลองเปิดฟอร์มใหม่'));p.onchange=async()=>{const g=await thaiGeo(),prov=g.provinces.find(x=>th(x)===p.value);d.innerHTML='<option value="">เลือกอำเภอ</option>'+g.districts.filter(x=>String(x.province_id)===String(prov?.id)).map(x=>`<option value="${esc(label(x))}" data-id="${x.id}">${esc(label(x))}</option>`).join('');d.disabled=!prov;s.innerHTML='<option value="">เลือกตำบล</option>';s.disabled=true;if(old?.district){const row=g.districts.find(x=>String(x.province_id)===String(prov?.id)&&(label(x)===old.district||th(x)===old.district));if(row){d.value=label(row);d.dispatchEvent(new Event('change'))}}};d.onchange=async()=>{const g=await thaiGeo(),districtId=d.selectedOptions[0]?.dataset.id;s.innerHTML='<option value="">เลือกตำบล</option>'+g.subdistricts.filter(x=>String(x.district_id)===String(districtId)).map(x=>`<option value="${esc(label(x))}" data-zip="${x.zip_code||''}">${esc(label(x))}</option>`).join('');s.disabled=!districtId;if(old?.subdistrict){const row=[...s.options].find(x=>x.value===old.subdistrict||x.text===old.subdistrict);if(row)s.value=row.value}};s.onchange=()=>{zip.value=s.selectedOptions[0]?.dataset.zip||zip.value}}
function readFileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function openCustomerDocument(c,type){const key=type==='id'?'idDocument':'licenseDocument',data=c[key+'Data'],path=c[key+'Path'];if(data){const w=window.open();if(w)w.location.href=data;return}if(path&&onlineMode){const {data:result,error}=await supabaseClient.storage.from('customer-documents').createSignedUrl(path,60);if(error)return toast('เปิดไฟล์ไม่ได้ กรุณาตรวจ Storage policy');window.open(result.signedUrl,'_blank','noopener')}}
function normalizePhone(value){return String(value||'').replace(/\D/g,'')}
function bankAccountOpts(selected=''){return '<option value="">ยังไม่ระบุบัญชี</option>'+db.bankAccounts.filter(a=>a.active||a.id===selected).map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.nickname)} · ${esc(a.bank)} · ${esc(a.accountNumber)}</option>`).join('')}
function renderCompany(){const box=$('#company-preview');if(!box)return;const c=db.company||defaultCompany;box.innerHTML=`<div class="company-card-logo">${c.logo?`<img src="${esc(c.logo)}" alt="โลโก้บริษัท">`:'AB'}</div><div><h2>${esc(c.name||'ยังไม่ได้ระบุชื่อบริษัท')}</h2><p>${esc(c.address||'ยังไม่ได้ระบุที่อยู่')}</p><p>เลขประจำตัวผู้เสียภาษี ${esc(c.taxId||'—')} · โทร. ${esc(c.phone||'—')} · ${esc(c.email||'—')}</p></div>`}
function renderBankAccounts(){const tbody=$('#bank-accounts-table');if(!tbody)return;tbody.innerHTML=db.bankAccounts.map(a=>`<tr><td><b>${esc(a.nickname)}</b></td><td>${esc(a.bank)}</td><td>${esc(a.accountName)}</td><td>${esc(a.accountNumber)}</td><td><span class="status ${a.active?'status-confirmed':'status-completed'}">${a.active?'ใช้งาน':'ปิดใช้งาน'}</span></td><td><button class="text-button" data-edit-bank="${esc(a.id)}">แก้ไข</button><button class="text-button" data-toggle-bank="${esc(a.id)}">${a.active?'ปิด':'เปิด'}</button></td></tr>`).join('');$('#banks-empty').classList.toggle('hidden',db.bankAccounts.length>0);$$('[data-edit-bank]').forEach(b=>b.onclick=()=>bankAccountForm(b.dataset.editBank));$$('[data-toggle-bank]').forEach(b=>b.onclick=async()=>{const a=db.bankAccounts.find(x=>x.id===b.dataset.toggleBank);a.active=!a.active;await persist();toast('อัปเดตบัญชีธนาคารแล้ว')})}
function renderBankIncome(){const tbody=$('#bank-income-table');if(!tbody)return;const paid=db.bookings.filter(b=>b.paid&&b.status!=='cancelled'),rows=db.bankAccounts.map(a=>({name:`${a.nickname} · ${a.bank} · ${a.accountNumber}`,count:paid.filter(b=>b.bankAccountId===a.id).length,total:paid.filter(b=>b.bankAccountId===a.id).reduce((s,b)=>s+b.total,0)}));const unassigned=paid.filter(b=>!b.bankAccountId||!db.bankAccounts.some(a=>a.id===b.bankAccountId));if(unassigned.length)rows.push({name:'ยังไม่ระบุบัญชี',count:unassigned.length,total:unassigned.reduce((s,b)=>s+b.total,0)});tbody.innerHTML=rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.count} รายการ</td><td><b>${money(r.total)}</b></td></tr>`).join('');$('#bank-income-empty').classList.toggle('hidden',rows.length>0)}
function companyForm(){const c={...defaultCompany,...db.company};openModal('ข้อมูลบริษัท','ข้อมูลนี้จะปรากฏบนหัวใบเสร็จ ใบกำกับภาษี และใบเสนอราคา',`<form id="company-form"><div class="form-grid"><div class="field full"><label>ชื่อร้าน / บริษัท *</label><input name="name" required value="${esc(c.name)}"></div><div class="field full"><label>ที่อยู่สำหรับออกเอกสาร *</label><textarea name="address" required>${esc(c.address)}</textarea></div><div class="field"><label>เลขประจำตัวผู้เสียภาษี</label><input name="taxId" maxlength="13" value="${esc(c.taxId)}"></div><div class="field"><label>เบอร์โทรศัพท์</label><input name="phone" value="${esc(c.phone)}"></div><div class="field"><label>อีเมล</label><input name="email" type="email" value="${esc(c.email)}"></div><div class="field"><label>สถานะ VAT</label><select name="vatRegistered"><option value="false" ${c.vatRegistered?"":"selected"}>ไม่ได้จด VAT</option><option value="true" ${c.vatRegistered?"selected":""}>จด VAT 7%</option></select></div><div class="field full"><label>โลโก้ร้าน</label><input name="logoFile" type="file" accept="image/*"><small>อัปโหลดรูปสำหรับแสดงบนเอกสาร A4</small>${c.logo?`<img class="company-logo-preview" src="${esc(c.logo)}" alt="โลโก้ปัจจุบัน">`:''}</div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกข้อมูลบริษัท</button></div></form>`);$('.cancel-modal').onclick=closeModal;$('#company-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,x=Object.fromEntries(new FormData(f));if(x.taxId&&!/^\d{13}$/.test(x.taxId))return toast('เลขผู้เสียภาษีต้องมี 13 หลัก');if(x.vatRegistered==='true'&&!/^\d{13}$/.test(x.taxId))return toast('ร้านที่จด VAT ต้องระบุเลขผู้เสียภาษี 13 หลัก');const logoFile=f.elements.logoFile.files[0];let logo=c.logo;if(logoFile){if(!logoFile.type.startsWith('image/'))return toast('กรุณาเลือกไฟล์รูปภาพ');logo=await compressCarPhoto(logoFile)}db.company={name:x.name.trim(),address:x.address.trim(),taxId:x.taxId||'',phone:x.phone||'',email:x.email||'',logo,vatRegistered:x.vatRegistered==='true'};await persist();closeModal();toast('บันทึกข้อมูลบริษัทแล้ว')}}
function bankAccountForm(id=''){const old=db.bankAccounts.find(a=>a.id===id);openModal(old?'แก้ไขบัญชีธนาคาร':'เพิ่มบัญชีธนาคาร','ข้อมูลบัญชีที่ใช้รับชำระค่าเช่า',`<form id="bank-form"><div class="form-grid"><div class="field"><label>ชื่อเรียกบัญชี *</label><input name="nickname" required value="${esc(old?.nickname||'')}" placeholder="เช่น บัญชีรับค่าเช่า"></div><div class="field"><label>ธนาคาร *</label><input name="bank" required value="${esc(old?.bank||'')}" placeholder="เช่น ธนาคารกสิกรไทย"></div><div class="field full"><label>ชื่อบัญชี *</label><input name="accountName" required value="${esc(old?.accountName||'')}"></div><div class="field full"><label>เลขที่บัญชี *</label><input name="accountNumber" required value="${esc(old?.accountNumber||'')}"></div>${old?`<div class="field"><label>สถานะ</label><select name="active"><option value="true" ${old.active?'selected':''}>ใช้งาน</option><option value="false" ${!old.active?'selected':''}>ปิดใช้งาน</option></select></div>`:''}</div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกบัญชี</button></div></form>`);$('.cancel-modal').onclick=closeModal;$('#bank-form').onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.currentTarget)),same=db.bankAccounts.find(a=>a.accountNumber===x.accountNumber&&a.id!==old?.id);if(same)return toast('เลขที่บัญชีนี้มีในระบบแล้ว');const a={...(old||{}),id:old?.id||'BANK-'+Date.now().toString().slice(-7),nickname:x.nickname.trim(),bank:x.bank.trim(),accountName:x.accountName.trim(),accountNumber:x.accountNumber.trim(),active:x.active?x.active==='true':true};if(old)Object.assign(old,a);else db.bankAccounts.push(a);await persist();closeModal();toast('บันทึกบัญชีธนาคารแล้ว')}}
function documentHeader(type,number,date,c){const shop={...defaultCompany,...db.company},customerAddress=c?.taxAddress||c?.address||'—',billTo=c?`<div class="bill-to"><b>ลูกค้า</b><strong>${esc(c.taxName||c.name||'—')}</strong>${c.taxType==='company'?`<span>${esc(c.branch||'สำนักงานใหญ่')}</span>`:''}<span>${esc(customerAddress)}</span><span>เลขประจำตัวผู้เสียภาษี ${esc(c.taxId||'—')}</span></div>`:'<div class="bill-to"><b>เอกสารภายในบริษัท</b><strong>ทะเบียนข้อมูลลูกค้า</strong></div>';return `<div class="document-heading"><div class="document-shop">${shop.logo?`<img class="document-logo" src="${esc(shop.logo)}" alt="โลโก้">`:''}<h1>${esc(shop.name)}</h1><p>${esc(shop.address||'')}</p><p>เลขประจำตัวผู้เสียภาษี ${esc(shop.taxId||'—')}</p><p>โทร. ${esc(shop.phone||'—')} · ${esc(shop.email||'')}</p></div><div class="document-bill"><div class="document-title">${esc(type)}</div><p><b>เลขที่เอกสาร</b> ${esc(number)}</p><p><b>วันที่</b> ${esc(dateFmt(date))}</p>${billTo}</div></div>`}
function documentTable(rows,total,deposit=0,bank=null,showVat=false){const registered=Boolean(db.company?.vatRegistered),base=total/1.07,vat=total-base;return `<table class="document-lines"><thead><tr><th>ลำดับ</th><th>รายการ</th><th>จำนวน</th><th>ราคา</th><th>จำนวนเงิน</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.title)}</td><td>${esc(r.qty||1)}</td><td>${money(r.price)}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table><div class="document-totals">${showVat&&registered?`<div><span>มูลค่าก่อนภาษี</span><b>${money(base)}</b></div><div><span>ภาษีมูลค่าเพิ่ม 7% (รวมในยอด)</span><b>${money(vat)}</b></div>`:`<div><span>รวมเป็นเงิน</span><b>${money(total)}</b></div>`}<div><span>เงินมัดจำ</span><b>${money(deposit)}</b></div><div class="document-grand"><span>ยอดสุทธิ${showVat&&registered?' (รวม VAT)':''}</span><b>${money(total)}</b></div></div>${bank?`<div class="document-bank"><b>ช่องทางชำระเงิน</b><span>${esc(bank.nickname)} · ${esc(bank.bank)} · ${esc(bank.accountName)} · ${esc(bank.accountNumber)}</span></div>`:''}<div class="document-signatures"><div>ผู้รับเงิน / ผู้มีอำนาจลงนาม</div><div>ลูกค้า</div></div>`}
function receiptMarkup(b,type){const c=customer(b.customerId),v=car(b.carId),isInvoice=type==='invoice',extras=b.extraCharges||[],base=b.total-extras.reduce((s,x)=>s+Number(x.amount),0),rows=[{title:`ค่าเช่ารถ ${v?.name||''} (${b.days} วัน)`,qty:b.days,price:base/b.days,amount:base},...extras.map(x=>({title:x.title,qty:1,price:Number(x.amount),amount:Number(x.amount)}))],bank=db.bankAccounts.find(a=>a.id===b.bankAccountId);return `<article class="document-page">${documentHeader(isInvoice?'ใบกำกับภาษี / ใบเสร็จรับเงิน':'ใบเสร็จรับเงิน',`${b.id}-${isInvoice?'INV':'REC'}`,todayISO(),c)}<div class="document-reference"><span>ทะเบียนรถ ${esc(v?.plate||'—')}</span><span>ระยะเวลา ${dtFmt(b.start)} ถึง ${dtFmt(b.end)}</span><span>ประกัน ${esc(b.insurance||'—')} · วงเงิน ${money(b.insuranceCoverage)}</span></div>${documentTable(rows,b.total,b.deposit,bank,isInvoice)}<div class="document-payment">สถานะชำระเงิน: ${b.paid?'ชำระแล้ว':'รอชำระ'} · ช่องทาง: ${esc(b.payment||'—')}</div><p class="document-thanks">ขอบคุณที่ใช้บริการ AB CARRENT</p></article>`}
function printBookingDocument(id,type){const b=db.bookings.find(x=>x.id===id);if(!b)return;const invoice=type==='invoice';if(invoice&&!db.company?.vatRegistered)return toast('ตั้งค่าสถานะจด VAT ในหน้าข้อมูลบริษัทก่อนพิมพ์ใบกำกับภาษี');openModal(invoice?'ใบกำกับภาษี':'ใบเสร็จรับเงิน',`เอกสาร A4 เลขที่ ${b.id}`,`${receiptMarkup(b,type)}<div class="form-actions print-controls"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-document">พิมพ์เอกสาร A4</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-document').onclick=async()=>{if(invoice)b.taxInvoicePrintedAt=new Date().toISOString();else b.receiptPrintedAt=new Date().toISOString();await persist();window.print();toast('บันทึกสถานะพิมพ์แล้ว')}}
function printQuote(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;const c=customer(q.customerId),v=car(q.carId),extras=q.extraCharges||[],base=q.total-extras.reduce((s,x)=>s+Number(x.amount),0),rows=[{title:`ค่าเช่ารถ ${v?.name||''} (${q.days} วัน)`,qty:q.days,price:base/q.days,amount:base},...extras.map(x=>({title:x.title,qty:1,price:Number(x.amount),amount:Number(x.amount)}))];openModal('ใบเสนอราคา',`เอกสาร A4 เลขที่ ${q.id}`,`<article class="document-page">${documentHeader('ใบเสนอราคา',q.id,q.created,c)}<div class="document-reference"><span>รถ ${esc(v?.name||'—')} · ${esc(v?.plate||'')}</span><span>ช่วงเวลา ${dtFmt(q.start)} ถึง ${dtFmt(q.end)}</span><span>ประกัน ${esc(q.insurance||'—')} · วงเงิน ${money(q.insuranceCoverage)}</span></div>${documentTable(rows,q.total,q.deposit,null,true)}<p class="document-thanks">ใบเสนอราคานี้ยังไม่ถือเป็นการยืนยันการจอง โปรดยืนยันกับบริษัทก่อนชำระเงิน</p></article><div class="form-actions print-controls"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-quote">พิมพ์ใบเสนอราคา A4</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-quote').onclick=()=>window.print()}
function printCustomers(){const rows=db.customers.slice().sort((a,b)=>a.name.localeCompare(b.name,'th')).map((c,i)=>`<tr><td>${i+1}</td><td>${esc(c.name)}${c.taxType==='company'?`<small>${esc(c.branch||'สำนักงานใหญ่')}</small>`:''}</td><td>${esc(c.phone)}</td><td>${esc(c.email||'—')}</td><td>${esc(c.taxId||'—')}</td><td>${esc(c.taxAddress||'—')}</td></tr>`).join('');openModal('พิมพ์ข้อมูลลูกค้า','รายการลูกค้าสำหรับพิมพ์ A4',`<article class="document-page customer-print-page">${documentHeader('ทะเบียนข้อมูลลูกค้า',`CUS-${todayISO().replaceAll('-','')}`,todayISO(),null)}<table class="document-lines"><thead><tr><th>#</th><th>ชื่อ / สาขา</th><th>โทรศัพท์</th><th>อีเมล</th><th>เลขผู้เสียภาษี</th><th>ที่อยู่</th></tr></thead><tbody>${rows||'<tr><td colspan="6">ไม่มีข้อมูลลูกค้า</td></tr>'}</tbody></table></article><div class="form-actions print-controls"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-customer-list">พิมพ์ A4</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-customer-list').onclick=()=>window.print()}
function customerForm(id=''){const old=id?customer(id):null,geo=`<div class="field"><label>จังหวัด</label><select name="province" id="customer-province"><option value="">เลือกจังหวัด</option></select></div><div class="field"><label>อำเภอ</label><select name="district" id="customer-district" disabled><option value="">เลือกอำเภอ</option></select></div><div class="field"><label>ตำบล</label><select name="subdistrict" id="customer-subdistrict" disabled><option value="">เลือกตำบล</option></select></div><div class="field"><label>รหัสไปรษณีย์</label><input name="postalCode" id="customer-postal" value="${esc(old?.postalCode||'')}"></div>`;openModal(old?'แก้ไขข้อมูลลูกค้า':'เพิ่มลูกค้า','เบอร์โทรศัพท์ใช้เป็นรหัสหลักของลูกค้าและแยกโฟลเดอร์เอกสาร',`<form id="customer-form"><div class="form-grid"><div class="field full"><label>เบอร์โทรศัพท์ * (ใช้ป้องกันข้อมูลซ้ำ)</label><input name="phone" id="customer-phone" required inputmode="numeric" value="${esc(old?.phone||'')}" placeholder="0812345678"></div><div class="field full"><label>ชื่อ–นามสกุล / ชื่อบริษัท *</label><input name="name" required value="${esc(old?.name||'')}"></div><div class="field"><label>อีเมล</label><input name="email" type="email" value="${esc(old?.email||'')}"></div><div class="field"><label>LINE ID</label><input name="line" value="${esc(old?.line||'')}"></div><div class="field"><label>ประเภทผู้เสียภาษี</label><select name="taxType" id="tax-type"><option value="individual" ${old?.taxType!=='company'?'selected':''}>บุคคลธรรมดา</option><option value="company" ${old?.taxType==='company'?'selected':''}>นิติบุคคล</option></select></div><div class="field"><label>เลขบัตรประชาชน / เลขผู้เสียภาษี *</label><input name="taxId" id="customer-tax-id" inputmode="numeric" maxlength="13" pattern="[0-9]{13}" required value="${esc(old?.taxId||old?.license||'')}"></div><div class="field"><label>เลขใบขับขี่</label><input name="license" value="${esc(old?.license||'')}"></div><div class="field full"><label>ชื่อบนเอกสารภาษี</label><input name="taxName" value="${esc(old?.taxName||old?.name||'')}"></div><div class="field full ${old?.taxType==='company'?'':'hidden'}" id="branch-field"><label>สาขา / สำนักงานใหญ่</label><input name="branch" value="${esc(old?.branch||'สำนักงานใหญ่')}" placeholder="สำนักงานใหญ่ หรือสาขาที่ ..."></div><div class="field full"><label>ที่อยู่สำหรับใบกำกับภาษี (บ้านเลขที่ / หมู่ / ถนน) *</label><textarea name="taxAddress" required>${esc(old?.taxAddress||old?.address||'')}</textarea></div>${geo}<div class="field full"><label>ไฟล์ PDF บัตรประชาชน</label><input type="file" name="idDocument" accept="application/pdf"><small>${old?.idDocumentPath||old?.idDocumentData?'มีไฟล์บันทึกแล้ว':'เลือกไฟล์ PDF สูงสุด 10 MB'}</small></div><div class="field full"><label>ไฟล์ PDF ใบขับขี่</label><input type="file" name="licenseDocument" accept="application/pdf"><small>${old?.licenseDocumentPath||old?.licenseDocumentData?'มีไฟล์บันทึกแล้ว':'เลือกไฟล์ PDF สูงสุด 10 MB'}</small></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกข้อมูลลูกค้า</button></div></form>`);$('.cancel-modal').onclick=closeModal;setupThaiAddress(old);$('#tax-type').onchange=e=>$('#branch-field').classList.toggle('hidden',e.target.value!=='company');$('#customer-phone').oninput=e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,10);$('#customer-tax-id').oninput=e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,13);$('#customer-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,x=Object.fromEntries(new FormData(f)),phone=normalizePhone(x.phone),taxId=normalizePhone(x.taxId);if(!/^0\d{8,9}$/.test(phone))return toast('เบอร์โทรศัพท์ต้องขึ้นต้นด้วย 0 และมี 9–10 หลัก');if(db.customers.some(c=>normalizePhone(c.phone)===phone&&c.id!==old?.id))return toast('เบอร์โทรศัพท์นี้มีในระบบแล้ว');if(!/^\d{13}$/.test(taxId))return toast('เลขบัตรประชาชน / เลขผู้เสียภาษีต้องมี 13 หลัก');if(db.customers.some(c=>c.taxId===taxId&&c.id!==old?.id))return toast('เลขประจำตัวผู้เสียภาษีนี้มีในระบบแล้ว');const files=[f.elements.idDocument.files[0],f.elements.licenseDocument.files[0]];for(const file of files)if(file&&(file.type!=='application/pdf'||file.size>(onlineMode?10:2)*1024*1024))return toast('เลือกเฉพาะไฟล์ PDF ขนาดไม่เกิน 10 MB');const customerId=phone,record={...(old||{}),id:customerId,name:x.name.trim(),phone,email:x.email||'',line:x.line||'',license:x.license||'',taxType:x.taxType,taxName:x.taxName||x.name,taxId,taxAddress:[x.taxAddress,x.subdistrict,x.district,x.province,x.postalCode].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(' '),province:x.province||'',district:x.district||'',subdistrict:x.subdistrict||'',postalCode:x.postalCode||'',branch:x.taxType==='company'?(x.branch||'สำนักงานใหญ่'):'',address:'',idDocumentPath:old?.idDocumentPath||'',licenseDocumentPath:old?.licenseDocumentPath||'',idDocumentData:old?.idDocumentData||'',licenseDocumentData:old?.licenseDocumentData||''};try{if(files[0])record.idDocumentData=await readFileData(files[0]);if(files[1])record.licenseDocumentData=await readFileData(files[1])}catch{return toast('อ่านไฟล์เอกสารไม่สำเร็จ')}if(old&&old.id!==customerId){db.bookings.filter(b=>b.customerId===old.id).forEach(b=>b.customerId=customerId);db.quotes.filter(q=>q.customerId===old.id).forEach(q=>q.customerId=customerId);db.customers.splice(db.customers.indexOf(old),1);db.customers.push(record)}else if(old)Object.assign(old,record);else db.customers.push(record);await persist();closeModal();toast(old?'บันทึกข้อมูลลูกค้าแล้ว':'เพิ่มลูกค้าแล้ว')}}
function bookingActions(id){const b=db.bookings.find(x=>x.id===id);if(!b)return;const editable=new Date(b.start).setHours(0,0,0,0)>new Date().setHours(0,0,0,0);openModal(`รายการ ${b.id}`,`${customer(b.customerId)?.name||''} · ${car(b.carId)?.name||''}`,`<div class="receipt-info"><div><span>รับรถ</span><br>${dtFmt(b.start)}</div><div><span>คืนรถ</span><br>${dtFmt(b.end)}</div><div><span>ยอดรวม</span><br>${money(b.total)}</div><div><span>สถานะ</span><br>${statusLabel[b.status]}</div></div><div class="field"><label>บัญชีรับชำระ</label><select id="booking-paid-bank">${bankAccountOpts(b.bankAccountId||'')}</select></div><div class="form-actions action-wrap"><button class="secondary-button" id="receipt-btn">พิมพ์ใบเสร็จ</button><button class="secondary-button" id="invoice-btn">พิมพ์ใบกำกับภาษี</button><button class="secondary-button" id="paid-btn" ${b.paid?'disabled':''}>${b.paid?'ชำระแล้ว':'บันทึกว่าชำระแล้ว'}</button>${editable?'<button class="secondary-button" id="edit-booking-btn">แก้ไขรายการ</button>':''}<select id="status-change" class="secondary-button">${Object.entries(statusLabel).map(([k,v])=>`<option value="${k}" ${b.status===k?'selected':''}>${v}</option>`).join('')}</select></div>`);$('#receipt-btn').onclick=()=>printBookingDocument(id,'receipt');$('#invoice-btn').onclick=()=>printBookingDocument(id,'invoice');$('#paid-btn').onclick=async()=>{const account=$('#booking-paid-bank').value;if(!account)return toast('เลือกบัญชีรับชำระก่อนบันทึกว่าชำระแล้ว');b.bankAccountId=account;b.paid=true;await persist();closeModal();toast('บันทึกการชำระเงินและบัญชีแล้ว')};if(editable)$('#edit-booking-btn').onclick=()=>bookingForm(id);$('#status-change').onchange=async e=>{b.status=e.target.value;await persist();closeModal();toast('อัปเดตสถานะรายการแล้ว')}}
function renderQuotes(){const table=$('#quotes-table');if(!table)return;const rows=(db.quotes||[]).slice().sort((a,b)=>b.created.localeCompare(a.created));table.innerHTML=rows.map(q=>`<tr><td>${esc(q.id)}<span class="subtext">${dateFmt(q.created)}</span></td><td>${esc(customer(q.customerId)?.name||'')}</td><td>${esc(car(q.carId)?.name||'')}<span class="subtext">${esc(car(q.carId)?.plate||'')}</span></td><td>${dtFmt(q.start)} – ${dtFmt(q.end)}<span class="subtext">${q.days} วัน</span></td><td><b>${money(q.total)}</b></td><td><span class="status status-${q.status==='converted'?'confirmed':q.status==='cancelled'?'cancelled':'quoted'}">${({quoted:'เสนอราคาแล้ว',converted:'เปลี่ยนเป็นรายการเช่าแล้ว',expired:'หมดอายุ',cancelled:'ยกเลิก'})[q.status]||q.status}</span></td><td><button class="text-button" data-quote-print="${esc(q.id)}">พิมพ์ใบเสนอราคา</button>${q.status==='quoted'?`<button class="text-button" data-quote-convert="${esc(q.id)}">สร้างรายการเช่า</button>`:''}</td></tr>`).join('');$('#quotes-empty').classList.toggle('hidden',rows.length>0);$$('[data-quote-convert]').forEach(b=>b.onclick=()=>bookingForm('',b.dataset.quoteConvert));$$('[data-quote-print]').forEach(b=>b.onclick=()=>printQuote(b.dataset.quotePrint))}
function renderCustomers(){const term=($('#customer-search')?.value||'').toLowerCase(),rows=db.customers.slice().sort((a,b)=>a.name.localeCompare(b.name,'th')).filter(c=>`${c.name} ${c.phone} ${c.email} ${c.taxId} ${c.line}`.toLowerCase().includes(term));$('#customers-table').innerHTML=rows.map(c=>{const bs=db.bookings.filter(b=>b.customerId===c.id&&b.status!=='cancelled');return `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc(c.name.replace('คุณ','').slice(0,1))}</span><div><b>${esc(c.name)}</b>${c.taxType==='company'?`<span class="subtext">${esc(c.branch||'')}</span>`:''}</div></div></td><td>${esc(c.phone)}</td><td>${esc(c.email||'—')}</td><td>${esc(c.taxId||'—')}</td><td>${bs.length}</td><td><b>${money(bs.reduce((s,b)=>s+b.total,0))}</b></td><td><button class="row-action" data-edit-customer="${esc(c.id)}">⋯</button></td></tr>`}).join('');$('#customers-empty').classList.toggle('hidden',rows.length>0);$$('[data-edit-customer]').forEach(x=>x.onclick=()=>customerActions(x.dataset.editCustomer))}
function quoteForm(){if(!db.cars.length||!db.customers.length)return toast('เพิ่มรถและลูกค้าก่อนออกใบเสนอราคา');openModal('ออกใบเสนอราคา','กำหนดลูกค้า รถ และช่วงเวลาเช่า',`<form id="quote-form"><div class="form-grid"><div class="field full"><label>ลูกค้า *</label><select name="customerId" required>${customerOpts()}</select></div><div class="field full"><label>รถที่ว่าง *</label><select name="carId" id="quote-car" required>${carOpts()}</select></div><div class="field"><label>รับรถ *</label><input name="start" type="datetime-local" value="${todayISO()}T09:00" required></div><div class="field"><label>คืนรถ *</label><input name="end" type="datetime-local" value="${isoOffset(1)}T09:00" required></div><div class="field"><label>มัดจำ (บาท)</label><input name="deposit" type="number" min="0" value="0"></div><div class="field"><label>ประกัน / รายละเอียด</label><input name="insurance"></div><div class="field"><label>วงเงินประกัน (บาท)</label><input name="insuranceCoverage" type="number" min="0" value="0"></div><div class="field"><label>ค่าใช้จ่ายเพิ่มเติม</label><input name="extraTitle" placeholder="ค่ารถไปส่ง"></div><div class="field"><label>จำนวนเงินเพิ่ม (บาท)</label><input name="extraAmount" type="number" min="0" value="0"></div><div class="field full"><div class="price-preview"><span id="quote-calc">คำนวณราคา</span><b id="quote-total">฿0</b></div></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกใบเสนอราคา</button></div></form>`);$('.cancel-modal').onclick=closeModal;const f=$('#quote-form'),updateCars=()=>{const chosen=f.carId.value,available=db.cars.filter(c=>c.available&&!hasConflict(c.id,f.start.value,f.end.value));f.carId.innerHTML=available.map(c=>`<option value="${c.id}" ${c.id===chosen?'selected':''}>${esc(c.name)} · ${esc(c.plate)}</option>`).join('')||'<option value="">ไม่มีรถว่าง</option>';const d=duration(f.start.value,f.end.value),extra=Number(f.extraAmount.value)||0;$('#quote-calc').textContent=d?`ค่าเช่า ${d} วัน + ค่าใช้จ่ายเพิ่มเติม ${money(extra)}`:'กรุณาตรวจสอบช่วงเวลา';$('#quote-total').textContent=money(d*(car(f.carId.value)?.price||0)+extra)};f.start.onchange=f.end.onchange=updateCars;f.carId.onchange=f.extraAmount.oninput=updateCars;updateCars();f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),days=duration(d.start,d.end);if(!days||!d.carId||hasConflict(d.carId,d.start,d.end))return toast('ช่วงเวลาไม่ถูกต้องหรือรถไม่ว่าง');const extraCharges=d.extraTitle&&Number(d.extraAmount)>0?[{title:d.extraTitle,amount:Number(d.extraAmount)}]:[];db.quotes.push({id:window.__nextQuoteId||'QT-'+Date.now().toString().slice(-7),customerId:d.customerId,carId:d.carId,start:d.start,end:d.end,days,total:days*car(d.carId).price+extraCharges.reduce((s,x)=>s+x.amount,0),deposit:Number(d.deposit)||0,insurance:d.insurance||'',insuranceCoverage:Number(d.insuranceCoverage)||0,extraCharges,status:'quoted',created:todayISO()});await persist();closeModal();show('quotes');renderQuotes();toast('ออกใบเสนอราคาแล้ว')}}

const bankNames=['ธนาคารกรุงเทพ','ธนาคารกรุงไทย','ธนาคารกรุงศรีอยุธยา','ธนาคารกสิกรไทย','ธนาคารเกียรตินาคินภัทร','ธนาคารซีไอเอ็มบี ไทย','ธนาคารทหารไทยธนชาต','ธนาคารทิสโก้','ธนาคารไทยเครดิต','ธนาคารไทยพาณิชย์','ธนาคารยูโอบี','ธนาคารแลนด์ แอนด์ เฮ้าส์','ธนาคารออมสิน','ธนาคารอาคารสงเคราะห์','ธนาคารเพื่อการเกษตรและสหกรณ์การเกษตร','ธนาคารพัฒนาวิสาหกิจขนาดกลางและขนาดย่อมแห่งประเทศไทย','ธนาคารแห่งประเทศไทย','ธนาคารอิสลามแห่งประเทศไทย'].sort((a,b)=>a.localeCompare(b,'th'));
const paymentRows=()=>db.payments||(db.payments=[]),notificationRows=()=>db.notifications||(db.notifications=[]),activitySeen=new Set();
db.payments=db.payments||[];db.notifications=db.notifications||[];
for(const group of [db.cars,db.customers,db.bookings,db.expenses,db.quotes,db.bankAccounts,db.payments,db.notifications])for(const row of group||[])activitySeen.add(row.id);
function documentPeriod(date){const d=new Date(date||todayISO()+'T12:00:00'),y=(d.getFullYear()+543)%100;return String(y).padStart(2,'0')+String(d.getMonth()+1).padStart(2,'0')}
function bookingCheckDigit(seven){let sum=0;for(let i=0;i<7;i++)sum+=Number(seven[i])*(8-i);return String((11-sum%11)%10)}
async function nextDocumentNumber(type,date){if(onlineMode){const {data,error}=await supabaseClient.rpc('next_document_number',{p_document_type:type,p_document_date:(date||todayISO()).slice(0,10)});if(error)throw error;return data}const period=['QT','RE','IV'].includes(type)?documentPeriod(date):documentPeriod(date).slice(0,2),key=`ab-carrent-counter-${type}-${period}`,n=(Number(localStorage.getItem(key))||0)+1,limit=type==='BK'?99999:9999;if(n>limit)throw new Error('เลขเอกสารครบจำนวนสูงสุดแล้ว');localStorage.setItem(key,String(n));if(type==='BK'){const seven=period+String(n).padStart(5,'0');return 'BK'+seven+bookingCheckDigit(seven)}return type+period+String(n).padStart(4,'0')}
function paymentFromDb(r){return{id:r.id,bookingId:r.booking_id,amount:Number(r.amount),method:r.payment_method,bankAccountId:r.bank_account_id||'',paidAt:r.paid_at,note:r.note||''}}
function paymentToDb(p){return{id:p.id,booking_id:p.bookingId,amount:p.amount,payment_method:p.method,bank_account_id:p.bankAccountId||null,paid_at:p.paidAt||new Date().toISOString(),note:p.note||null}}
function notificationFromDb(r){return{id:r.id,eventType:r.event_type,title:r.title,detail:r.detail||'',readAt:r.read_at||null,createdAt:r.created_at}}
function notificationToDb(n){return{id:n.id,event_type:n.eventType,title:n.title,detail:n.detail||'',read_at:n.readAt||null,created_at:n.createdAt}}
function appendActivity(type,title,detail){const n={id:crypto.randomUUID(),eventType:type,title,detail,readAt:null,createdAt:new Date().toISOString()};notificationRows().unshift(n);activitySeen.add(n.id)}
function detectNewActivity(){for(const [key,type,title,getDetail] of [['customers','customer','เพิ่มลูกค้า',x=>`${x.name} · ${x.phone}`],['cars','car','เพิ่มรถ',x=>`${x.name} · ${x.plate}`],['bookings','booking','สร้างรายการเช่า',x=>`${x.id} · ${customer(x.customerId)?.name||''}`],['quotes','quote','ออกใบเสนอราคา',x=>`${x.id} · ${customer(x.customerId)?.name||''}`],['payments','payment','บันทึกการชำระเงิน',x=>`${money(x.amount)} · ${x.method}`],['bankAccounts','bank','เพิ่มบัญชีธนาคาร',x=>`${x.nickname} · ${x.bank}`],['expenses','expense','บันทึกรายจ่าย',x=>`${x.title} · ${money(x.amount)}`]])for(const x of db[key]||[])if(!activitySeen.has(x.id)){activitySeen.add(x.id);appendActivity(type,title,getDetail(x))}}
function renderNotifications(){const list=$('#notification-list');if(!list)return;const rows=notificationRows().slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),unread=rows.filter(x=>!x.readAt).length;$('#notification-dot').classList.toggle('hidden',!unread);list.innerHTML=rows.length?rows.slice(0,40).map(n=>`<button type="button" class="notification-item ${n.readAt?'read':''}" data-notification="${esc(n.id)}"><b>${esc(n.title)}</b><span>${esc(n.detail)}</span><small>${new Date(n.createdAt).toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short'})}</small></button>`).join(''):'<div class="empty-small">ยังไม่มีการแจ้งเตือน</div>';$$('[data-notification]').forEach(b=>b.onclick=async()=>{const n=notificationRows().find(x=>x.id===b.dataset.notification);if(n&&!n.readAt){n.readAt=new Date().toISOString();await persist()}})}
function updateCompanyLogo(){const img=$('#sidebar-company-logo'),mark=$('#sidebar-brand-mark'),src=db.company?.logo||'';if(!img||!mark)return;img.src=src;img.classList.toggle('hidden',!src);mark.classList.toggle('hidden',Boolean(src));img.onerror=()=>{img.classList.add('hidden');mark.classList.remove('hidden')}}
