renderBookings=function(){const term=($('#booking-search')?.value||'').toLowerCase(),filter=$('#booking-filter')?.value||'all',rows=db.bookings.filter(b=>{const c=customer(b.customerId),v=car(b.carId);return(filter==='all'||b.status===filter)&&`${c?.name} ${v?.name} ${v?.plate} ${b.id}`.toLowerCase().includes(term)}).sort((a,b)=>b.created.localeCompare(a.created));$('#bookings-table').innerHTML=rows.map(b=>bookingRow(b,true)).join('');$('#bookings-empty').classList.toggle('hidden',rows.length>0);$$('[data-booking]').forEach(el=>el.onclick=()=>bookingActions(el.dataset.booking));$$('[data-doc-booking]').forEach(el=>el.onclick=()=>printBookingDocument(el.dataset.docBooking,el.dataset.doc));$$('[data-payment-booking]').forEach(el=>el.onclick=()=>paymentForm(el.dataset.paymentBooking))};
bookingRow=function(b,showDocs=false){const c=customer(b.customerId),v=car(b.carId),payments=paymentRows().filter(p=>p.bookingId===b.id),received=payments.reduce((s,p)=>s+p.amount,0),balance=Math.max(0,b.total-received),docCell=showDocs?`<div class="doc-actions"><button class="text-button" data-doc="receipt" data-doc-booking="${esc(b.id)}">ใบเสร็จ</button><small class="print-state ${b.receiptPrintedAt?'printed':'pending'}">${b.receiptPrintedAt?'พิมพ์แล้ว':'ยังไม่พิมพ์'}</small><button class="text-button" data-doc="invoice" data-doc-booking="${esc(b.id)}">ใบกำกับภาษี</button><small class="print-state ${b.taxInvoicePrintedAt?'printed':'pending'}">${b.taxInvoicePrintedAt?'พิมพ์แล้ว':'ยังไม่พิมพ์'}</small></div>`:'';return `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc((c?.name||'?').replace('คุณ','').slice(0,1))}</span><div><b>${esc(c?.name||'ไม่พบข้อมูลลูกค้า')}</b><span class="subtext">${esc(b.id)}</span></div></div></td><td>${esc(v?.name||'รถถูกลบ')}<span class="subtext">${esc(v?.plate||'')}</span></td><td>${dtFmt(b.start)}</td><td>${dtFmt(b.end)}</td><td>${b.days} วัน</td><td><b>${money(b.total)}</b></td><td><div class="payment-cell"><b>รับแล้ว ${money(received)}</b><small>คงเหลือ ${money(balance)}</small><button class="text-button" data-payment-booking="${esc(b.id)}">＋ แจ้งชำระเงิน</button></div></td><td><span class="status status-${b.status}">${statusLabel[b.status]||b.status}</span></td>${showDocs?`<td>${docCell}</td>`:''}<td><button class="row-action" data-booking="${esc(b.id)}" title="จัดการ">⋯</button></td></tr>`};
renderFinance=function(){const received=paymentRows().reduce((s,p)=>s+p.amount,0),expenses=db.expenses.reduce((s,e)=>s+Number(e.amount),0),pending=db.bookings.filter(b=>b.status!=='cancelled').reduce((s,b)=>s+Math.max(0,b.total-paymentRows().filter(p=>p.bookingId===b.id).reduce((t,p)=>t+p.amount,0)),0);$('#fin-income').textContent=money(received);$('#fin-expenses').textContent=money(expenses);$('#fin-net').textContent=money(received-expenses);$('#fin-pending').textContent=money(pending);let entries=[...paymentRows().map(p=>({date:p.paidAt||todayISO(),title:`รับชำระ ${customer(db.bookings.find(b=>b.id===p.bookingId)?.customerId)?.name||''}`,category:'รายรับค่าเช่า',ref:p.bookingId,payment:`${p.method}${p.bankAccountId?' · '+(db.bankAccounts.find(a=>a.id===p.bankAccountId)?.nickname||''):''}`,amount:Number(p.amount)})),...db.expenses.map(e=>({date:e.date,title:`${e.title}${e.carId?' · '+(car(e.carId)?.name||'รถ'):' · ไม่ระบุรถ'}`,category:e.category,ref:e.id,payment:e.payment,amount:-Number(e.amount)}))].sort((a,b)=>b.date.localeCompare(a.date));const filter=$('#ledger-filter')?.value||'all';if(filter==='income')entries=entries.filter(e=>e.amount>=0);if(filter==='expense')entries=entries.filter(e=>e.amount<0);$('#ledger-table').innerHTML=entries.map(e=>`<tr><td>${dateFmt(e.date)}</td><td>${esc(e.title)}</td><td>${esc(e.category)}</td><td>${esc(e.ref)}</td><td>${esc(e.payment||'—')}</td><td class="${e.amount<0?'ledger-minus':'ledger-plus'}"><b>${e.amount<0?'−':'+'}${money(Math.abs(e.amount))}</b></td></tr>`).join('');$('#ledger-empty').classList.toggle('hidden',entries.length>0);const byBank=new Map();for(const p of paymentRows().filter(x=>x.bankAccountId)){const a=db.bankAccounts.find(x=>x.id===p.bankAccountId),key=a?.id||'';if(!key)continue;const z=byBank.get(key)||{a,count:0,total:0};z.count++;z.total+=p.amount;byBank.set(key,z)}$('#bank-income-table').innerHTML=[...byBank.values()].map(x=>`<tr><td>${esc(x.a.nickname)} · ${esc(x.a.bank)}</td><td>${x.count}</td><td><b>${money(x.total)}</b></td></tr>`).join('');$('#bank-income-empty').classList.toggle('hidden',byBank.size>0)};
bankAccountForm=function(id=''){const old=db.bankAccounts.find(a=>a.id===id);openModal(old?'แก้ไขบัญชีธนาคาร':'เพิ่มบัญชีธนาคาร','ข้อมูลบัญชีที่ใช้รับชำระค่าเช่า',`<form id="bank-form"><div class="form-grid"><div class="field"><label>ชื่อเรียกบัญชี *</label><input name="nickname" required value="${esc(old?.nickname||'')}" placeholder="เช่น บัญชีรับค่าเช่า"></div><div class="field"><label>ธนาคาร *</label><select name="bank" required><option value="">เลือกธนาคาร</option>${bankNames.map(n=>`<option ${old?.bank===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field full"><label>ชื่อบัญชี *</label><input name="accountName" required value="${esc(old?.accountName||'')}"></div><div class="field full"><label>เลขที่บัญชี *</label><input name="accountNumber" required value="${esc(old?.accountNumber||'')}"></div>${old?`<div class="field"><label>สถานะ</label><select name="active"><option value="true" ${old.active?'selected':''}>ใช้งาน</option><option value="false" ${!old.active?'selected':''}>ปิดใช้งาน</option></select></div>`:''}</div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกบัญชี</button></div></form>`);$('.cancel-modal').onclick=closeModal;$('#bank-form').onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.currentTarget)),same=db.bankAccounts.find(a=>a.accountNumber===x.accountNumber&&a.id!==old?.id);if(same)return toast('เลขที่บัญชีนี้มีในระบบแล้ว');const a={...(old||{}),id:old?.id||crypto.randomUUID(),nickname:x.nickname.trim(),bank:x.bank,accountName:x.accountName.trim(),accountNumber:x.accountNumber.trim(),active:x.active?x.active==='true':true};if(old)Object.assign(old,a);else db.bankAccounts.push(a);await persist();closeModal();toast('บันทึกบัญชีธนาคารแล้ว')}};
function paymentForm(bookingId){const b=db.bookings.find(x=>x.id===bookingId);if(!b)return;const rows=paymentRows().filter(p=>p.bookingId===bookingId),received=rows.reduce((s,p)=>s+p.amount,0),renderRows=()=>rows.map(p=>`<tr><td>${dateFmt(p.paidAt)}</td><td>${esc(p.method)}</td><td>${esc(db.bankAccounts.find(a=>a.id===p.bankAccountId)?.nickname||'—')}</td><td>${esc(p.note||'—')}</td><td><b>${money(p.amount)}</b></td></tr>`).join('')||'<tr><td colspan="5">ยังไม่มีการรับชำระ</td></tr>';const m=openModal(`แจ้งชำระเงิน · ${b.id}`,`${customer(b.customerId)?.name||''} · ยอดรวม ${money(b.total)} · รับแล้ว ${money(received)} · คงเหลือ ${money(Math.max(0,b.total-received))}`,`<div class="table-wrap payment-history"><table><thead><tr><th>วันที่</th><th>ช่องทาง</th><th>บัญชีรับเงิน</th><th>หมายเหตุ</th><th>จำนวนเงิน</th></tr></thead><tbody>${renderRows()}</tbody></table></div><form id="payment-form"><div class="form-grid"><div class="field"><label>จำนวนเงิน (บาท) *</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>ช่องทาง *</label><select name="method"><option>เงินสด</option><option>โอนเงิน</option><option>บัตรเครดิต</option><option>อื่นๆ</option></select></div><div class="field"><label>บัญชีรับโอน</label><select name="bankAccountId">${bankAccountOpts()}</select></div><div class="field"><label>วันเวลาที่ชำระ</label><input name="paidAt" type="datetime-local" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></div><div class="field full"><label>หมายเหตุ</label><input name="note" placeholder="เช่น รับเงินมัดจำ"></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ปิด</button><button class="primary-button">บันทึกการชำระเงิน</button></div></form>`);if(!m)return;$('.cancel-modal').onclick=closeModal;const f=$('#payment-form'),account=f.elements.bankAccountId;f.elements.method.onchange=()=>{account.disabled=f.elements.method.value!=='โอนเงิน';if(f.elements.method.value==='โอนเงิน')account.required=true;else{account.required=false;account.value=''}};f.elements.method.onchange();f.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(f)),amount=Number(x.amount);if(!(amount>0))return toast('กรอกยอดเงินให้มากกว่า 0');if(x.method==='โอนเงิน'&&!x.bankAccountId)return toast('เลือกบัญชีรับโอน');const payment={id:crypto.randomUUID(),bookingId,amount,method:x.method,bankAccountId:x.bankAccountId||'',paidAt:x.paidAt?new Date(x.paidAt).toISOString():new Date().toISOString(),note:x.note||''};try{if(onlineMode){const {error}=await supabaseClient.rpc('record_booking_payment',{p_payment_id:payment.id,p_booking_id:bookingId,p_amount:amount,p_payment_method:payment.method,p_bank_account_id:payment.bankAccountId||null,p_paid_at:payment.paidAt,p_note:payment.note||null});if(error)throw error}paymentRows().push(payment);if(paymentRows().filter(p=>p.bookingId===bookingId).reduce((s,p)=>s+p.amount,0)>=b.total)b.paid=true;await persist();toast('บันทึกรับชำระเงินแล้ว');paymentForm(bookingId)}catch(error){toast(error.message||'บันทึกการชำระเงินไม่สำเร็จ')}}}
receiptMarkup=function(b,type,docNumber){const c=customer(b.customerId),v=car(b.carId),isInvoice=type==='invoice',extras=b.extraCharges||[],base=b.total-extras.reduce((s,x)=>s+Number(x.amount),0),rows=[{title:`ค่าเช่ารถ ${v?.name||''} (${b.days} วัน)`,qty:b.days,price:base/b.days,amount:base},...extras.map(x=>({title:x.title,qty:1,price:Number(x.amount),amount:Number(x.amount)}))],bank=db.bankAccounts.find(a=>a.id===b.bankAccountId),payments=paymentRows().filter(p=>p.bookingId===b.id),paid=payments.reduce((s,p)=>s+p.amount,0),paymentInfo=payments.length?`<section class="document-payment-list"><h4>ประวัติการรับชำระเงิน</h4><table><thead><tr><th>วันที่</th><th>ช่องทาง / บัญชี</th><th>หมายเหตุ</th><th>จำนวนเงิน</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${dateFmt(p.paidAt)}</td><td>${esc(p.method)}${p.bankAccountId?' · '+esc(db.bankAccounts.find(a=>a.id===p.bankAccountId)?.nickname||''):''}</td><td>${esc(p.note||'—')}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="3">รับชำระรวม ${money(paid)} · คงเหลือ ${money(Math.max(0,b.total-paid))}</th><th>${money(paid)}</th></tr></tfoot></table></section>`:`<div class="document-payment">ยังไม่มีรายการรับชำระ · คงเหลือ ${money(b.total)}</div>`;return `<article class="document-page">${documentHeader(isInvoice?'ใบกำกับภาษี / ใบเสร็จรับเงิน':'ใบเสร็จรับเงิน',docNumber||b.receiptNumber||b.id,todayISO(),c)}<div class="document-reference"><span>เลขที่เช่า ${esc(b.id)}</span><span>ทะเบียนรถ ${esc(v?.plate||'—')}</span><span>ระยะเวลา ${dtFmt(b.start)} ถึง ${dtFmt(b.end)}</span><span>ประกัน ${esc(b.insurance||'—')} · วงเงิน ${money(b.insuranceCoverage)}</span></div>${documentTable(rows,b.total,b.deposit,bank,isInvoice)}${paymentInfo}<p class="document-thanks">ขอบคุณที่ใช้บริการ AB CARRENT</p></article>`};
printBookingDocument=async function(id,type){const b=db.bookings.find(x=>x.id===id);if(!b)return;const invoice=type==='invoice';if(invoice&&!db.company?.vatRegistered)return toast('ตั้งค่าสถานะจด VAT ในหน้าข้อมูลบริษัทก่อนพิมพ์ใบกำกับภาษี');try{const field=invoice?'taxInvoiceNumber':'receiptNumber',kind=invoice?'IV':'RE';if(onlineMode){const {data,error}=await supabaseClient.rpc('ensure_booking_document_number',{p_booking_id:b.id,p_document_type:kind,p_document_date:todayISO()});if(error)throw error;b[field]=data}else if(!b[field])b[field]=await nextDocumentNumber(kind,todayISO());await persist();openModal(invoice?'ใบกำกับภาษี':'ใบเสร็จรับเงิน',`เอกสาร A4 เลขที่ ${b[field]}`,`${receiptMarkup(b,type,b[field])}<div class="form-actions print-controls"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-document">พิมพ์เอกสาร A4</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-document').onclick=async()=>{if(invoice)b.taxInvoicePrintedAt=new Date().toISOString();else b.receiptPrintedAt=new Date().toISOString();await persist();window.print();toast('บันทึกสถานะพิมพ์แล้ว')}}catch(error){toast(error.message||'สร้างเลขเอกสารไม่สำเร็จ')}};
const oldStartRemote=startRemoteSession;startRemoteSession=async function(user){await oldStartRemote(user);if(!syncedState||!activeAdmin)return;try{const [payments,notifications,documents]=await Promise.all([requireSupabaseResult(supabaseClient.from('booking_payments').select('*').order('paid_at')),requireSupabaseResult(supabaseClient.from('notifications').select('*').order('created_at',{ascending:false})),requireSupabaseResult(supabaseClient.from('bookings').select('id,receipt_number,tax_invoice_number'))]);db.payments=payments.map(paymentFromDb);db.notifications=notifications.map(notificationFromDb);for(const d of documents){const b=db.bookings.find(x=>x.id===d.id);if(b){b.receiptNumber=d.receipt_number||'';b.taxInvoiceNumber=d.tax_invoice_number||''}}syncedState=deepCopy(db);activitySeen.clear();for(const k of ['cars','customers','bookings','expenses','quotes','bankAccounts','payments','notifications'])for(const x of db[k]||[])activitySeen.add(x.id);applyDefaultSettings();render()}catch(error){console.error('AB CARRENT payments/notifications load:',error);toast('โหลดประวัติรับชำระหรือการแจ้งเตือนไม่สำเร็จ')}};
syncRemoteState=async function(){if(!syncedState)return;const target=deepCopy(db),specs=[{key:'cars',table:'cars',to:carToDb},{key:'customers',table:'customers',to:customerToDb},{key:'bankAccounts',table:'bank_accounts',to:bankAccountToDb},{key:'bookings',table:'bookings',to:b=>({...bookingToDb(b),receipt_number:b.receiptNumber||null,tax_invoice_number:b.taxInvoiceNumber||null})},{key:'expenses',table:'expenses',to:expenseToDb},{key:'quotes',table:'quotes',to:quoteToDb},{key:'payments',table:'booking_payments',to:paymentToDb},{key:'notifications',table:'notifications',to:notificationToDb}];for(const s of specs){const before=new Map((syncedState[s.key]||[]).map(x=>[x.id,JSON.stringify(x)])),changed=(target[s.key]||[]).filter(x=>before.get(x.id)!==JSON.stringify(x));if(s.key==='cars')for(const c of changed)await uploadCarPhoto(c);if(s.key==='customers')for(const c of changed)await uploadCustomerDocuments(c);if(changed.length)await requireSupabaseResult(supabaseClient.from(s.table).upsert(changed.map(s.to)))}if(JSON.stringify(target.company)!==JSON.stringify(syncedState.company))await requireSupabaseResult(supabaseClient.from('company_settings').upsert({id:'default',profile:target.company}));for(const s of [...specs].reverse()){const now=new Set((target[s.key]||[]).map(x=>x.id)),deleted=(syncedState[s.key]||[]).filter(x=>!now.has(x.id)).map(x=>x.id);if(deleted.length)await requireSupabaseResult(supabaseClient.from(s.table).delete().in('id',deleted))}for(const c of target.customers){const live=customer(c.id);if(live)for(const key of ['idDocument','licenseDocument'])if(live[key+'Data']&&c[key+'Path'])live[key+'Data']=''}for(const savedCar of target.cars){const liveCar=car(savedCar.id);if(liveCar&&liveCar.image?.startsWith('data:')&&savedCar.image!==liveCar.image)liveCar.image=savedCar.image}syncedState=deepCopy(target)};
persist=function(){detectNewActivity();if(!onlineMode){localStorage.setItem(KEY,JSON.stringify(db));render();return Promise.resolve()}render();remoteSaveQueue=remoteSaveQueue.then(syncRemoteState).catch(error=>{const message=error?.code==='23P01'?'รถคันนี้ถูกจองทับช่วงเวลาโดยรายการอื่นแล้ว':(error?.message||'บันทึกฐานข้อมูลไม่สำเร็จ');db=deepCopy(syncedState||db);render();toast(message);console.error('AB CARRENT Supabase save:',error)});return remoteSaveQueue};
document.addEventListener('click',async e=>{const toggle=e.target.closest('#notification-toggle'),panel=$('#notification-panel');if(toggle){panel.classList.toggle('hidden');toggle.setAttribute('aria-expanded',String(!panel.classList.contains('hidden')));return}if(e.target.closest('#notifications-read-all')){for(const n of notificationRows())n.readAt=n.readAt||new Date().toISOString();await persist();return}if(e.target.closest('#notifications-clear')){db.notifications=[];await persist();return}if(!e.target.closest('#notification-panel'))panel?.classList.add('hidden')});
$('#new-booking').onclick=()=>bookingForm();document.addEventListener('submit',async e=>{const f=e.target;if(!['booking-form','quote-form'].includes(f.id)||f.dataset.numberHook)return;const original=f.onsubmit;if(typeof original!=='function')return;if(f.id==='booking-form'&&$('#modal h2')?.textContent?.includes('แก้ไข'))return;f.dataset.numberHook='1';e.preventDefault();e.stopImmediatePropagation();try{const date=new FormData(f).get('start'),type=f.id==='booking-form'?'BK':'QT',number=await nextDocumentNumber(type,date);if(type==='BK')window.__nextBookingId=number;else window.__nextQuoteId=number;const before=new Set(db.bookings.map(b=>b.id));await original.call(f,e);if(type==='BK'){const created=db.bookings.find(b=>!before.has(b.id));if(created?.paid&&!paymentRows().some(p=>p.bookingId===created.id)){paymentRows().push({id:crypto.randomUUID(),bookingId:created.id,amount:created.total,method:created.payment||'เงินสด',bankAccountId:created.bankAccountId||'',paidAt:new Date().toISOString(),note:'รับชำระเมื่อสร้างรายการ'});await persist()}}}catch(error){toast(error.message||'สร้างเลขเอกสารไม่สำเร็จ')}finally{delete window.__nextBookingId;delete window.__nextQuoteId;delete f.dataset.numberHook}},true);
const fullRentalBookingRow=bookingRow;bookingRow=function(b,showDocs=false){if(showDocs)return fullRentalBookingRow(b,true);const c=customer(b.customerId),v=car(b.carId);return `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc((c?.name||'?').replace('คุณ','').slice(0,1))}</span><div><b>${esc(c?.name||'ไม่พบข้อมูลลูกค้า')}</b><span class="subtext">${esc(b.id)}</span></div></div></td><td>${esc(v?.name||'รถถูกลบ')}<span class="subtext">${esc(v?.plate||'')}</span></td><td>${dtFmt(b.start)}</td><td>${b.days} วัน<span class="subtext">คืน ${dtFmt(b.end)}</span></td><td><b>${money(b.total)}</b></td><td><span class="status status-${b.status}">${statusLabel[b.status]||b.status}</span></td><td></td></tr>`};

