const quoteBookingTableState={bookings:{sort:'id',direction:'desc',page:1,size:10},quotes:{sort:'id',direction:'desc',page:1,size:10}};
function tablePageControls(key){const tableId=key==='bookings'?'bookings-table':'quotes-table',table=document.getElementById(tableId),panel=table?.closest('.table-panel');if(!panel)return null;let controls=panel.querySelector('.table-pagination');if(!controls){controls=document.createElement('div');controls.className='table-pagination';controls.innerHTML=`<label>แสดง <select data-page-size="${key}"><option value="10">10</option><option value="20">20</option><option value="50">50</option><option value="100">100</option></select> รายการต่อหน้า</label><span data-page-info="${key}"></span><div><button type="button" class="secondary-button" data-page-prev="${key}">ก่อนหน้า</button><button type="button" class="secondary-button" data-page-next="${key}">ถัดไป</button></div>`;panel.append(controls)}const select=controls.querySelector(`[data-page-size="${key}"]`);if(select)select.value=String(quoteBookingTableState[key].size);return controls}
function setupSortableHeaders(key){const table=document.getElementById(key==='bookings'?'bookings-table':'quotes-table');if(!table)return;const keys=key==='bookings'?['id','customer','car','start','end','days','total','received',null,'status',null,null]:['id','customer','car','start','total','status',null];table.closest('table').querySelectorAll('thead th').forEach((th,i)=>{const sortKey=keys[i];if(!sortKey)return;th.dataset.sortKey=sortKey;th.dataset.sortTable=key;th.classList.add('sortable-heading');let mark=th.querySelector('.sort-indicator');if(!mark){mark=document.createElement('span');mark.className='sort-indicator';th.append(mark)}const st=quoteBookingTableState[key];mark.textContent=st.sort===sortKey?(st.direction==='desc'?' ↓':' ↑'):''})}
function sortPageRows(key,rows){const st=quoteBookingTableState[key],value=(row,k)=>{if(k==='id')return String(row.id||'');if(k==='car')return car(row.carId)?.name||'';if(k==='customer')return customer(row.customerId)?.name||'';if(k==='start')return row.start||'';if(k==='end')return row.end||'';if(k==='days')return Number(row.days)||0;if(k==='total')return Number(row.total)||0;if(k==='received')return paymentRows().filter(p=>p.bookingId===row.id).reduce((s,p)=>s+Number(p.amount||0),0);if(k==='status')return row.status||'';return''};return rows.sort((a,b)=>{const av=value(a,st.sort),bv=value(b,st.sort),cmp=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'th',{numeric:true,sensitivity:'base'});return st.direction==='desc'?-cmp:cmp})}
